// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** The ordering picker. `price` is present only for users who order or manage tests (technicians never see it). */
export interface LabTestListItemOut {
  test_id: number;
  code: string;
  name: string;
  section: string;
  sample_type: string;
  price?: number | null;
  turnaround_minutes: number | null;
  emergency_turnaround_minutes: number | null;
  availability: "InHouse" | "SendOut";
  send_out_partner_id: number | null;
  /** SendOut: tell the patient the test goes to this laboratory */
  send_out_partner_name: string | null;
  available_24h: boolean;
  notifiable_disease: string | null;
  is_active: boolean;
  row_version: number;
  metric_schema: MetricDefOut[];
}

/** One result field of a test (the test's metric schema); keys a newer catalogue adds are passed through. */
export interface MetricDefOut {
  key: string;
  label: string;
  unit?: string | null;
  type: "number" | "text";
  decimals?: number | null;
  required?: boolean | null;
  /** Reference ranges: {"male":[13.5,17.5],"female":[12,15.5],"default":[12,17.5]} */
  ref?: Record<string, number[]> | null;
  critical?: CriticalRangeOut | null;
}

export interface CriticalRangeOut {
  low?: number | null;
  high?: number | null;
  /** A text metric: the values that are critical */
  values?: string[] | null;
}

export interface LabTestIn {
  code: string;
  name: string;
  section?: string;
  sample_type?: string;
  metric_schema: MetricDef[];
  price?: number | string;
  /** Routine orders: from the sample's receipt to the published result (MSDS AAC 4) */
  turnaround_minutes?: number | null;
  /** Urgent and STAT orders (MSDS AAC 4); none: the setting lab_turnaround_emergency_minutes */
  emergency_turnaround_minutes?: number | null;
  availability?: "InHouse" | "SendOut";
  /** SendOut: the partner laboratory (GET /diagnostic-partners) */
  send_out_partner_id?: number | null;
  /** One of the basic tests available round the clock (MSDS AAC 1 v) */
  available_24h?: boolean;
  /** The priority disease a positive result means (reported to the health authority) */
  notifiable_disease?: string | null;
}

export interface MetricDef {
  key: string;
  label: string;
  unit?: string | null;
  type?: "number" | "text";
  decimals?: number | null;
  required?: boolean;
  /** {"male":[13.5,17.5],"female":[12,15.5],"default":[12,17.5]} */
  ref?: Record<string, number[]> | null;
  /** {"low": 7, "high": 20}, or for a text metric {"values": ["Positive"]} */
  critical?: CriticalDef | null;
}

export interface CriticalDef {
  low?: number | null;
  high?: number | null;
  /** A text metric: the values that are critical, e.g. ["Positive", "Reactive"] (a priority disease) */
  values?: string[] | null;
}

export interface LabTestOut {
  test_id: number;
  code: string;
  name: string;
  section: string;
  sample_type: string;
  metric_schema_jsonb: MetricDefOut[];
  price: number;
  turnaround_minutes: number | null;
  emergency_turnaround_minutes: number | null;
  availability: "InHouse" | "SendOut";
  send_out_partner_id: number | null;
  available_24h: boolean;
  notifiable_disease: string | null;
  is_active: boolean;
  row_version: number;
}

export interface LabTestUpdate {
  name?: string | null;
  section?: string | null;
  sample_type?: string | null;
  metric_schema?: MetricDef[] | null;
  turnaround_minutes?: number | null;
  emergency_turnaround_minutes?: number | null;
  availability?: "InHouse" | "SendOut" | null;
  send_out_partner_id?: number | null;
  available_24h?: boolean | null;
  notifiable_disease?: string | null;
  is_active?: boolean | null;
  /** Optimistic concurrency: the row_version you loaded */
  row_version?: number | null;
}

