/** One active staff member as a picker shows them (GET /staff/lookup): the facts on their badge and the registration their stamp prints, nothing else. */
export interface StaffLookupOut {
  /** The id a form's staff field takes (contrast_doctor_id, employee_id, ...) */
  employee_id: number;
  emp_number: string;
  full_name: string;
  designation: string;
  department_name: string | null;
  /** The council they are registered with (PMDC: a doctor or dentist; PNC: a nurse); null: none */
  license_type: "PMDC" | "PNC" | "Other" | null;
  /** As their stamp prints it, e.g. "PMDC 12345-P"; null: no number on file */
  registration: string | null;
}

/** Active lab test catalogue (for the ordering picker) — GET /api/v1/lab/tests (who may call: holders of lab.requisition.create or lab.test.manage or lab.requisition.view). */
export function listTests(query?: { q?: string | null }): Promise<LabTestListItemOut[]> {
  return api<LabTestListItemOut[]>("GET", withQuery(`/lab/tests`, query), undefined);
}

/** Add a test with its metric schema — POST /api/v1/lab/tests (who may call: holders of lab.test.manage). */
export function createTest(body: LabTestIn): Promise<LabTestOut> {
  return api<LabTestOut>("POST", `/lab/tests`, body, { idempotent: true });
}

/** Edit a test (not its price) — PATCH /api/v1/lab/tests/{test_id} (who may call: holders of lab.test.manage). */
export function updateTest(test_id: number, body: LabTestUpdate): Promise<LabTestOut> {
  return api<LabTestOut>("PATCH", `/lab/tests/${test_id}`, body);
}

/** Set a test price (Lab Admin; history kept) — PUT /api/v1/lab/tests/{test_id}/price (who may call: holders of lab.price.update). */
export function setPrice(test_id: number, body: PriceIn): Promise<LabTestPriceOut> {
  return api<LabTestPriceOut>("PUT", `/lab/tests/${test_id}/price`, body);
}

/** Reagent bill-of-materials of a test — GET /api/v1/lab/tests/{test_id}/bom (who may call: holders of lab.bom.manage or lab.reagent.manage). */
export function getBom(test_id: number): Promise<BomLineOut[]> {
  return api<BomLineOut[]>("GET", `/lab/tests/${test_id}/bom`, undefined);
}

/** Replace the reagent BOM of a test — PUT /api/v1/lab/tests/{test_id}/bom (who may call: holders of lab.bom.manage). */
export function putBom(test_id: number, body: BomIn): Promise<BomLineOut[]> {
  return api<BomLineOut[]>("PUT", `/lab/tests/${test_id}/bom`, body);
}

/** Reagents with live stock (FEFO-eligible) and next expiry — GET /api/v1/lab/reagents (who may call: holders of lab.reagent.manage or lab.bom.manage). */
export function reagents(): Promise<ReagentStockOut[]> {
  return api<ReagentStockOut[]>("GET", `/lab/reagents`, undefined);
}

/** Add a reagent — POST /api/v1/lab/reagents (who may call: holders of lab.reagent.manage). */
export function createReagent(body: ReagentIn): Promise<ReagentOut> {
  return api<ReagentOut>("POST", `/lab/reagents`, body, { idempotent: true });
}

/** Receive a reagent batch (stock in) — POST /api/v1/lab/reagent-batches (who may call: holders of lab.reagent.manage). */
export function receiveBatch(body: ReagentBatchIn): Promise<ReagentBatchOut> {
  return api<ReagentBatchOut>("POST", `/lab/reagent-batches`, body, { idempotent: true });
}

/** Write off reagent stock (expiry / damage / count adjustment) — POST /api/v1/lab/reagent-adjustments (who may call: holders of lab.reagent.manage). */
export function adjustReagent(body: ReagentAdjustIn): Promise<ReagentMovementOut> {
  return api<ReagentMovementOut>("POST", `/lab/reagent-adjustments`, body, { idempotent: true });
}

/** Lab profit: revenue − reagent COGS, contractor share — GET /api/v1/lab/dashboard (who may call: holders of lab.dashboard.view). */
export function dashboard(query?: { date_from?: string | null; date_to?: string | null }): Promise<LabDashboardOut> {
  return api<LabDashboardOut>("GET", withQuery(`/lab/dashboard`, query), undefined);
}

/** Set the lab revenue-share agreement from a date — PUT /api/v1/lab/contractor (who may call: holders of lab.dashboard.view and lab.price.update). */
export function setContractor(body: ContractorIn): Promise<ContractorShareOut> {
  return api<ContractorShareOut>("PUT", `/lab/contractor`, body);
}

/** Find a staff member for a form (badge facts only) — GET /api/v1/staff/lookup (who may call: any logged-in user). */
export function lookupStaff(query: { q: string; department_id?: number | null; license_type?: "PMDC" | "PNC" | null; limit?: number }): Promise<StaffLookupOut[]> {
  return api<StaffLookupOut[]>("GET", withQuery(`/staff/lookup`, query), undefined);
}
